command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/transfer-item-budget-20261006"
$baseline="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$accepted="36f4f400239beac526a5bf273c51a81000701642"
$candidate="2d0d6c84ecfa2fa55239c7713ef709b1f2546360"
$temp=Join-Path $env:RUNNER_TEMP ("transfer-budget-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before transfer-budget final validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before transfer-budget final validation: $branchSha"}

  & git diff --quiet $accepted $candidate -- app src tests/winui/m22/m22_transfer_fixture.cpp tests/winui/m23/m23_native_fixture.cpp tests/winui/test_transfer_budget_contract.py tests/winui/test_transfer_budget_gui.py tests/winui/test_file_operation_controller_contract.py tests/winui/test_localization_contract.py
  if($LASTEXITCODE -ne 0){throw "accepted product/native/GUI contract files changed after #460"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\m22\test_native.py tests\winui\m23\test_native.py
  if($LASTEXITCODE -ne 0){throw "native wrapper Python static check failed"}

  & python -X utf8 -m unittest tests.winui.test_transfer_budget_contract tests.winui.test_file_operation_controller_contract tests.winui.test_localization_contract
  if($LASTEXITCODE -ne 0){throw "transfer-budget source contracts failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $baseline --head $candidate
  if($LASTEXITCODE -ne 0){throw "FAST validation failed"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  Write-Host ("TRANSFER_BUDGET_REVIEWED_PRODUCT="+$accepted)
  Write-Host ("TRANSFER_BUDGET_FINAL_CANDIDATE="+$candidate)
  Write-Host "TRANSFER_BUDGET_FINAL_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
